WFJ.Data.add("gossip", {
  ["4a0e6222d889dfb6"] = { "La lama stessa doveva essere forgiata in una cerimonia con i figli degli Aspetti. Un evento davvero raro... Perché non solo un drago avrebbe dovuto scaldare e plasmare di sua volontà il metallo incantato con il proprio respiro, ma avrebbe anche dovuto contenere la furia del proprio incantamento usando il proprio sangue per temprarlo.", "." },
  ["4a0fa18c1e282e3f"] = { "Coraggio, ⟦Alliance=Alleanza⟧! Ricacciate questi furfanti dalla ⟦Alterac Valley=Valle d'Alterac⟧!", "." },
  ["4a11528a28f5d2e2"] = { "Ehi, fai attenzione con quel kodo! Faresti meglio a controllare quella bestia prima che io ti dia il merito!", "." },
  ["4a1623d4cb9f29d6"] = { "La guerra contro l'⟦Horde=Orda⟧ è al culmine, {name}. Per l'⟦Alliance=Alleanza⟧ è un momento di grande bisogno, ed è indispensabile che ognuno di noi faccia la sua parte.", "." },
  ["4a174beb1671ba3f"] = { "Una forza riporta %s a Xoroth!", "." },
  ["4a1a6abe24e25cb9"] = { "Hai fatto strada... è ora di vedere il capo. Va' da Josef e digli che sei <pronto/pronta>.", "." },
  ["4a1f9b5a6230b89b"] = { "Lasciate questo luogo!", "." },
  ["4a2516ad52f74c34"] = { "Sarete giudicati per aver profanato questo suolo sacro! Le leggi degli Antichi non si sfidano! Gli intrusi saranno annientati!", "." },
  ["4a26ca3cb1624b5d"] = { "Continua così. Questo flagello sarà estirpato!", "." },
  ["4a2bb1b0f6991722"] = { "Ma aspetta...", "." },
  ["4a2d9806133dc0e1"] = { "%s comincia a scavare...", "." },
  ["4a32c12be4f0acb5"] = { "L'infestazione del Flagello cresce nelle ⟦Blasted Lands=Terre Devastate⟧. Serve ogni guerriero abile per arginare la marea della loro invasione.\n\nNecropoli rimanenti: $2280W", "." },
  ["4a455cef76cb6204"] = { "Andiamocene da questo posto.", "." },
  ["4a458c0c4fdd5566"] = { "Cos'è questo? Gli orchi si avvicinano già?", "." },
  ["4a497f443eea70ec"] = { "Riesci a vedermi? Sai quanto mi ignorano quassù solo perché nessuno può vedermi? Che sollievo avere finalmente qualcuno con cui parlare!\n\nAllora, deve averti mandato qualche membro ancora vivo della mia vecchia compagnia di mercenari, giusto? Certo che sì!\n\nMa basta chiacchiere: c'è un sacco di lavoro per te e per me, se vuoi rimettere le cose a posto e restituire a lord Valthalak il suo spirito!", "." },
  ["4a50aaa181fce321"] = { "Voglio proprio vedere cos'ha da offrire un ammasso di bulloni.", "." },
  ["4a583d7f4489607f"] = { "Verme va su amo, amo va in acqua. Pesce è in acqua, nostro pesce.", "." },
  ["4a6d6aa8cb401786"] = { "La tua intromissione negli affari demoniaci finisce ORA, mortale! Affronta il grande corruttore: Xandivious!", "." },
  ["4a71710a5f536154"] = { "Una voce tonante rimbomba dalla pietra...\n\nPercepisco il tuo Medaglione della Ricezione, cultista, ma non hai un anello del comando? Sei davvero un comandante del ⟦Twilight's Hammer=Martello del Crepuscolo⟧, o fai solo commissioni per i tuoi superiori?", "." },
  ["4a74aefe9356e2dc"] = { "Sei qui per aiutare con la consegna? Miran è quasi pronto.", "." },
  ["4a8050c2b12837c9"] = { "Il maestro delle viverne", "." },
  ["4a8a5cfc4ddde639"] = { "Non siamo che oscurità e ombre. Eterni. Invisibili.", "." },
  ["4a944102668c1ffc"] = { "Altro pane, ragazzo!", "." },
  ["4a9a6b16c51c737d"] = { "Certo. Dammi un segnale luminoso, Ryson.", "." },
  ["4aa19bf7198c2cc7"] = { "Quello che vedi davanti a te è un vilsegugio. Fra i talenti naturali di questa creatura ci sono Blocca Incantesimo e altre abilità che lo rendono impareggiabile contro un avversario sintonizzato con la magia.", "." },
  ["4aa7abd34f931ec9"] = { "Questi marinai d'acqua dolce sono qui per le renne! Infilzateli!", "." },
  ["4aaabfa33b8e5557"] = { "Informazioni sul Chromatic Carapace.", "." },
  ["4ab7366eb0cb81fe"] = { "%s assorbe l'energia della benedizione della saggezza e la reindirizza sotto forma di impulso antimagia.", "." },
  ["4abb2ac4dcbe3070"] = { "Tutte le statue tornano nella loro posizione originale.\n\nOra bisogna ricominciare la sequenza, dall'inizio.", "." },
  ["4ac13ce7d65afb82"] = { "Devo costruire un faro per questo meraviglioso congegno!", "." },
  ["4ac89a0e0aed36d0"] = { "Elortha no Shadra\n\nDea dei Ragni, Madre del Veleno, Danzatrice della Seta, Amore della Morte.", "." },
  ["4ad2b929bb0b8fd9"] = { "Ammirate! Il Blue Recluse dà un banchetto in suo onore!", "." },
  ["4add2c8a91ea1ed9"] = { "Hai già l'acqua, {name}? Si racconta che le rovine siano protette da grandi creature della natura che non gradiscono i visitatori, ma potrebbero essere solo leggende per spaventare i nemici degli Elfi della Notte.\n\nIn ogni caso, fa' attenzione.", "." },
  ["4ae8cf4db434637f"] = { "Momenti come questi mi rendono tutto sentimentale...", "." },
  ["4af1b1c86d32f8ac"] = { "L'infestazione del Flagello cresce ad Azshara. Serve ogni guerriero abile per arginare la marea della loro invasione.\n\nNecropoli rimanenti: $2279W", "." },
  ["4af80ea11d463fa7"] = { "Mia carissima Torta, è passato così tanto tempo dalla mia partenza. Finalmente siamo di nuovo insieme. Finalmente il nostro amore può sbocciare di nuovo.", "." },
  ["4afa1d6342197f05"] = { "Salve! Cosa ti porta a ⟦Winterspring=Fontefredda⟧? Queste terre fredde e sconfinate possono sembrare desolate, ma questo è un luogo pieno di segreti...", "." },
  ["4afb8562784458a1"] = { "I Titani avevano lasciato questo mondo da tempo. A difenderlo c'erano solo gli elfi della notte che un tempo abitavano questa zona. Oh, cielo! Il passo successivo è affascinante!", "." },
  ["4afb860db926bb19"] = { "Sono in missione. Una missione! Una missione alla ricerca di nuove leghe e metalli più duri per la più grande invenzione di tutte!!", "." },
})
